INSERT INTO form_pattern (pattern_code, pattern_name, description) VALUES
('register_log', '등록대장류', '"NO/구분/일자/내용/담당/확인" 골격에 업무별 항목 2~3개만 다른 구조. 예: 리스크등록대장, 변경관리대장, 설비등록대장, 공급자리스트 등.'),
('single_report', '단건 보고서류', '담당/검토/승인 3단 결재란 + 본문 항목으로 구성. 예: 부적합보고서, 사고보고서, 검사성적서, 설계개발검토서.'),
('checklist', '체크리스트/선택형', '체크박스 선택형 항목이 핵심. 예: 5S활동결과표, 심사체크리스트, 부적합보고서의 구분란.'),
('nested_evaluation', '중첩헤더 평가표', '상위헤더 하나에 하위컬럼 여러 개가 반복되는 구조. 예: 리스크등록대장의 기존관리/개선조치(각 심각도·발생가능성·등급), 공급자실적평가표.');
INSERT INTO doc_type (doc_type_code, doc_type_name, category, applicable_std, applicable_label, clause_ref, remark, subcategory, subcategory_group, subcategory_letter, display_code, source_project_title, source_original) VALUES
('M001', '품질/환경/안전보건 경영매뉴얼', 'manual', '["q","e","hs"]'::jsonb, '공통(순수)', '전체', '규격 선택에 따라 해당 장(章)만 포함하여 자동 구성. 단독 선택 시 매뉴얼명도 해당 규격명으로 자동 치환(예: Q단독=품질경영매뉴얼).', NULL, NULL, NULL, NULL, NULL, NULL),
('P410', '조직의 상황관리', 'procedure', '["q","e","hs"]'::jsonb, '공통(순수)', '4.1', '코드 410=4,1,0 → 조항 4.1(4.1~4.4 전체를 대표). 원 샘플 코드 그대로 유지.', NULL, NULL, NULL, NULL, NULL, NULL),
('P530', '조직관리(역할, 책임 및 권한)', 'procedure', '["q","e","hs"]'::jsonb, '공통(순수)', '5.3', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('P610', '리스크 및 기회관리', 'procedure', '["q","e","hs"]'::jsonb, '공통(순수)', '6.1', '일반 사업 리스크·기회(6.1.1). 환경측면(E, 6.1.2)·위험성평가(HS, 6.1.2)는 별도 전용 절차서(P612/P614)로 분리.', NULL, NULL, NULL, NULL, NULL, NULL),
('P613', '법규 및 준수의무 검토', 'procedure', '["q","e","hs"]'::jsonb, '공통(고유조항포함)', '6.1.3', '2026-08-17 사용자 확정: 환경(E)·안전보건(HS) 법규검토 절차를 Q,E,HS 순으로 하나의 절차서(613)로 통합. 규격별 검토 체크리스트는 절차서 내 고유조항으로 구성.', NULL, NULL, NULL, NULL, NULL, NULL),
('P620', '방침목표관리', 'procedure', '["q","e","hs"]'::jsonb, '공통(순수)', '6.2', '품질/환경/안전보건 목표를 하나의 절차서에서 통합 관리.', NULL, NULL, NULL, NULL, NULL, NULL),
('P630', '변경관리', 'procedure', '["q","e","hs"]'::jsonb, '공통(순수)', '6.3', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('P715', '계측기 및 모니터링장비관리', 'procedure', '["q","e","hs"]'::jsonb, '공통(순수)', '7.1.5', '2026-08-17 사용자 확정: 품질전용에서 공통으로 재분류(환경측정장비·노출측정장비 포함).', NULL, NULL, NULL, NULL, NULL, NULL),
('P720', '교육훈련', 'procedure', '["q","e","hs"]'::jsonb, '공통(순수)', '7.2', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
