('P854', '보존, 인도 및 사후관리', 'procedure', '["q"]'::jsonb, 'Q전용', '8.5.4', '8.5.4~8.5.6 포함(보존/인도/변경관리).', NULL, NULL, NULL, NULL, NULL, NULL),
('P860', '창고관리 및 출하관리', 'procedure', '["q"]'::jsonb, 'Q전용', '8.6', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('P912', '고객만족관리', 'procedure', '["q"]'::jsonb, 'Q전용', '9.1.2', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('P913', '검사 및 시험', 'procedure', '["q"]'::jsonb, 'Q전용', '9.1.3', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('P612', '환경측면 파악 및 평가', 'procedure', '["e"]'::jsonb, 'E전용', '6.1.2', 'ISO14001 고유 조항(EMS의 6.1.2). HS의 6.1.2(P614)와 조항번호가 같아 코드로는 구분됨.', NULL, NULL, NULL, NULL, NULL, NULL),
('P811', '폐기물관리', 'procedure', '["e"]'::jsonb, 'E전용', '8.1.1', '코드 811=8,1,1 → 조항 8.1(운영기획 및 관리) 세부 1번.', NULL, NULL, NULL, NULL, NULL, NULL),
('P812', '화학물질 및 유해물질관리', 'procedure', '["e"]'::jsonb, 'E전용', '8.1.2', '코드 812=8,1,2 → 조항 8.1 세부 2번. HS의 위험물질관리(P814 도급/구매)와 내용 일부 중복 가능.', NULL, NULL, NULL, NULL, NULL, NULL),
('P911', '환경성과평가 및 모니터링측정', 'procedure', '["e"]'::jsonb, 'E전용', '9.1.1', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('P614', '유해위험요인 파악 및 위험성평가', 'procedure', '["hs"]'::jsonb, 'HS전용', '6.1.2', 'ISO45001 고유 조항(OHSMS의 6.1.2). E의 6.1.2(P612)와 조항번호가 같아 코드 순번을 613(법규검토) 다음인 614로 offset.', NULL, NULL, NULL, NULL, NULL, NULL),
('P540', '근로자 협의 및 참여', 'procedure', '["hs"]'::jsonb, 'HS전용', '5.4', '코드 540=5,4,0 → 조항 5.4(ISO45001 고유, 리더십 장).', NULL, NULL, NULL, NULL, NULL, NULL),
('P814', '도급업체 및 구매관리(안전보건)', 'procedure', '["hs"]'::jsonb, 'HS전용', '8.1.4', '코드 814=8,1,4 → 조항 8.1.4(외주/조달/도급업체 관리).', NULL, NULL, NULL, NULL, NULL, NULL),
('P914', '사고조사 및 사건분석', 'procedure', '["hs"]'::jsonb, 'HS전용', '9.1.4', '코드 914=9,1,4 → 조항 9.1(모니터링, 측정, 분석 및 평가) 세부 4번으로 편성. 10.2(시정조치)와 연계.', NULL, NULL, NULL, NULL, NULL, NULL),
('P915', '건강관리 및 모니터링(근로자 건강검진 등)', 'procedure', '["hs"]'::jsonb, 'HS전용', '9.1.5', '코드 915=9,1,5 → 조항 9.1 세부 5번.', NULL, NULL, NULL, NULL, NULL, NULL),
('P825', '비상사태 대비 및 대응', 'procedure', '["e","hs"]'::jsonb, 'EHS통합전용', '8.2', '2026-08-17 사용자 확정: 환경(E)·안전보건(HS) 비상사태 대응 절차를 하나로 통합(코드 825). 조항은 EMS/OHSMS 공통 8.2. Q의 8.2 계열(821,822)과 겹치지 않도록 순번 5 사용.', NULL, NULL, NULL, NULL, NULL, NULL),
('P612(HS-1)', '근골격계질환 예방관리', 'procedure', '["hs"]'::jsonb, 'HS전용', '6.1.2', '유해요인조사(3년 주기)→개선대책 수립→교육→보건관리 순의 전형적 PDCA 사이클. 조사방법·기록·서식 등 관리프로그램 운영체계가 문서의 골격. (조항코드 612는 E전용 ''환경측면 파악 및 평가''와 동일 조항 6.1.2 — 식별을 위해 HS-1 부여. 문서 내용상 인간공학적 위험성평가로 E영역 해당사항 없음)', NULL, NULL, NULL, NULL, NULL, NULL),
('P730', '작업중지요청', 'procedure', '["hs"]'::jsonb, 'HS전용', '7.3', '근로자의 작업중지·대피→관리감독자 보고→현장확인→개선조치→작업재개라는 처리절차와, 기록대장 및 결재란(작성/검토/승인)을 갖춘 서식이 첨부된 전형적 절차서 구조. (ISO45001 7.3-f ''근로자가 자신의 생명이나 건강에 긴급하고 심각한 위험을 초래할 수 있다고 생각하는 작업 상황에서 스스로 벗어날 수 있는 권한'' 조항에 직접 대응. 기존 사용 코드 없음. 근로자 안전 전용으로 E영역 해당사항 없음)', NULL, NULL, NULL, NULL, NULL, NULL),
('P811(HS-1)', '안전작업허가제', 'procedure', '["hs"]'::jsonb, 'HS전용', '8.1.1', '세부 기술기준이 다수 포함되어 있으나, 문서의 골격은 ''누가 작업허가서를 작성·입회·승인·발급·보존하는가''라는 허가서의 발행·승인·보존기간·효력에 관한 조직적 통제 절차. 허가절차 자체가 문서의 존재 이유. (조항코드 811은 E전용 ''폐기물관리''와 동일 조항 8.1.1 — 식별을 위해 HS-1 부여. 화기·밀폐공간·고소 등 작업자 안전허가가 본질로 E영역 해당사항 없음)', NULL, NULL, NULL, NULL, NULL, NULL),
('P812(HS-1)', '개인보호구 지급 및 관리', 'procedure', '["hs"]'::jsonb, 'HS전용', '8.1.2', '적격품 확인→구매담당자 월별 구매→부서장·관리감독자 청구→안전보건주관부서장 지급→보호구 지급대장 기록·보존→개인 보관책임→교환 요청이라는 부서 간 승인·기록 절차가 본문 핵심. (ISO45001 8.1.2-e ''적절한 개인보호구 착용'' 조항에 직접 대응. 조항코드 812는 E전용 ''화학물질 및 유해물질관리''와 동일 조항 — 근로자 착용 보호구에 한정되어 E영역 해당사항 없으므로 HS-1 부여)', NULL, NULL, NULL, NULL, NULL, NULL),
('P812(EHS-1)', '물질안전보건자료(MSDS) 관리', 'procedure', '["e","hs"]'::jsonb, 'EHS통합전용', '8.1.2', '구매요청부서(MSDS 확보)→취급·사용부서(게시·비치·교육)→수령부서(확보·배부)→안전담당자(현황관리·개정전파)로 이어지는 부서 간 문서 유통·관리 흐름. (조항코드 812는 E전용 ''화학물질 및 유해물질관리''와 동일 조항. MSDS는 근로자 노출관리(HS)뿐 아니라 화학물질의 환경유해성·누출/폐기 정보(E)에도 공용으로 사용되는 자료이므로 EHS통합전용으로 재분류, EHS-1 부여)', NULL, NULL, NULL, NULL, NULL, NULL),
('P812(HS-2)', '호흡기보호', 'procedure', '["hs"]'::jsonb, 'HS전용', '8.1.2', '호흡보호구 지급·선정부터 착용교육, 관리감독자·안전보건주관부서 간 다단계 보고·승인 체계, 정기점검·기록관리에 이르는 전사적 관리프로그램 구조. (조항코드 812는 E전용 ''화학물질 및 유해물질관리''와 동일 조항 — 근로자 호흡보호구 착용에 한정되어 E영역 해당사항 없으므로 HS-2 부여)', NULL, NULL, NULL, NULL, NULL, NULL),
('P814(EHS-1)', '조달(구매)관리', 'procedure', '["e","hs"]'::jsonb, 'EHS통합전용', '8.1.4', '안전보건관리책임자(검토·승인)-안전보건주관부서장(구매실행·지급)-관리감독자(재고관리·구매요청)로 이어지는 역할 분담과 구매요청→검토및승인→구매실시의 순차적 승인 워크플로우. (조항코드 814는 기존 HS전용 ''도급업체 및 구매관리(안전보건)''와 동일 조항 8.1.4. 본문 4.4.1 구매발주자료 포함사항에 ''사업장에 필요한 환경/안전보건 요구사항''이 명시되어 있어 EHS통합전용으로 재분류, EHS-1 부여)', NULL, NULL, NULL, NULL, NULL, NULL),
('P814(HS-1)', '도급사업 안전관리', 'procedure', '["hs"]'::jsonb, 'HS전용', '8.1.4', '도급업체 적격성 평가(안전보건수준평가 70점 기준), 계약 단계별 포함사항, 안전보건총괄책임자 지정, 협의체 구성·운영(분기 1회), 합동점검 등 원·하청 간 조직적 통제 절차. (조항코드 814는 기존 HS전용 ''도급업체 및 구매관리(안전보건)''와 동일 조항 8.1.4 — 본문상 ''작업환경측정''은 근로환경 측정이며 환경경영(E) 해당사항은 없어 HS-1 부여)', NULL, NULL, NULL, NULL, NULL, NULL),
('P911(HS-1)', '안전검사', 'procedure', '["hs"]'::jsonb, 'HS전용', '9.1.1', '안전보건주관부서장 검사계획 수립→안전보건관리책임자 결재→검사기관 선정·통보→검사 의뢰·실행→부적합 시정→결과기록 3년 보관이라는 승인·실행·기록 업무흐름. (조항코드 911은 E전용 ''환경성과평가 및 모니터링측정''과 동일 조항 9.1.1 — 산업안전보건법상 유해위험기계 법정검사로 E영역 해당사항 없어 HS-1 부여)', NULL, NULL, NULL, NULL, NULL, NULL),
